import{I as i,o as p,c as u,j as e,a as o,J as a,w as s,b6 as c}from"./chunks/framework.COUcLbTA.js";const h={style:{margin:"50px 0"}},b=JSON.parse('{"title":"Finding Great Ideas - From User Needs to Willingness to Pay","description":"Learn how to discover business opportunities from daily pain points, master systematic methodology for needs analysis, and transform ordinary ideas into product concepts that users are willing to pay for.","frontmatter":{"title":"Finding Great Ideas - From User Needs to Willingness to Pay","description":"Learn how to discover business opportunities from daily pain points, master systematic methodology for needs analysis, and transform ordinary ideas into product concepts that users are willing to pay for."},"headers":[],"relativePath":"en/stage-1/finding-great-idea/index.md","filePath":"en/stage-1/finding-great-idea/index.md"}'),g={name:"en/stage-1/finding-great-idea/index.md"},v=Object.assign(g,{setup(m){const n="About <strong>3 hours</strong>";return(y,t)=>{const r=i("ChapterIntroduction"),l=i("StepBar"),d=i("ClientOnly");return p(),u("div",null,[t[1]||(t[1]=e("h1",{id:"beginner-level-2-finding-great-ideas",tabindex:"-1"},[o("Beginner Level 2: Finding Great Ideas "),e("a",{class:"header-anchor",href:"#beginner-level-2-finding-great-ideas","aria-label":"Permalink to “Beginner Level 2: Finding Great Ideas”"},"​")],-1)),t[2]||(t[2]=e("h2",{id:"chapter-overview",tabindex:"-1"},[o("Chapter Overview "),e("a",{class:"header-anchor",href:"#chapter-overview","aria-label":"Permalink to “Chapter Overview”"},"​")],-1)),a(r,{duration:n,tags:["Need Discovery","Product Thinking","User Analysis","Business Model"],coreOutput:"3 validated product concepts",expectedOutput:"Actionable startup/product direction"},{default:s(()=>[...t[0]||(t[0]=[e("p",null,[o("Previously, we learned how to build things with AI IDE, but there's a more fundamental question: "),e("strong",null,"What to build?")],-1),e("p",null,[o(`Many people start by thinking "let's make an AI tool" or "let's create a social platform," only to find that nobody uses what they build. Where's the problem? `),e("strong",null,"They didn't find real needs.")],-1),e("p",null,[o("The harsher reality is: "),e("strong",null,"Many products solve problems, but users still won't pay for them.")],-1),e("p",null,"In this chapter, through Xiao Ming's story, we'll learn how to find product directions worth pursuing.",-1),e("p",null,[o("After completing this chapter, you'll have a "),e("strong",null,"complete methodology for finding ideas"),o(" and 3 validated product concepts.")],-1)])]),_:1}),e("div",h,[a(d,null,{default:s(()=>[a(l,{active:0,items:[{title:"Step 1",description:"Establish Criteria"},{title:"Step 2",description:"Discover Daily Pain Points"},{title:"Step 3",description:"Segment by User Groups"},{title:"Step 4",description:"Deep Dive into Scenarios"},{title:"Step 5",description:"Validate Needs"},{title:"Step 6",description:"Refine Product Concept"}]})]),_:1})]),t[3]||(t[3]=c(`<h2 id="step-1-establish-criteria-—-what-makes-users-willing-to-pay" tabindex="-1">Step 1: Establish Criteria — What Makes Users Willing to Pay <a class="header-anchor" href="#step-1-establish-criteria-—-what-makes-users-willing-to-pay" aria-label="Permalink to “Step 1: Establish Criteria — What Makes Users Willing to Pay”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Why is this chapter important?</p><p>Some might find it strange: &quot;Isn&#39;t this a course teaching Vibe Coding? Why learn &#39;finding needs&#39; first? Can&#39;t we just start coding?&quot;</p><p>Indeed, many programming courses on the market teach you to build projects directly: make a Todo List, a calculator, a personal blog... These projects can help you get familiar with syntax and tools, but the problem is:</p><p><strong>Wrong direction, the deeper you go, the more wrong you become.</strong></p><p>Imagine:</p><ul><li>You spend two weeks building a &quot;calendar management system,&quot; but there are already 100 better ones on the market</li><li>You make a &quot;calorie photo calculator,&quot; but users uninstall it after one use</li><li>You create a &quot;personal expense tracker,&quot; but even you can&#39;t be bothered to use it</li></ul><p>After completing these projects, can you put them on your resume? Probably not, because <strong>they don&#39;t solve real problems or create real value.</strong></p><p>The harsher truth is: since we&#39;re investing time in learning, why not aim for better results?</p><p>Since Vibe Coding lets us quickly turn ideas into products, we should learn to <strong>find ideas worth building.</strong> Train yourself in the most practical way — not by making &quot;practice projects,&quot; but by making &quot;products people want to use.&quot;</p><p>That&#39;s why we need to learn &quot;finding great ideas&quot; first.</p><hr><p><strong>In my opinion</strong>, time is precious. <strong>If you&#39;re going to do something, do it right</strong>, otherwise why not just play? As a responsibility, I&#39;ll do my best to support you in achieving excellence.</p><p>Even if no one believes you can do well, I&#39;ll steadfastly hope for your success. You&#39;ve chosen vibecoding to build products, so let&#39;s see how far you can go!</p></div><hr><h2 id="opening-the-story-of-independent-developer-xiao-ming" tabindex="-1">Opening: The Story of Independent Developer Xiao Ming <a class="header-anchor" href="#opening-the-story-of-independent-developer-xiao-ming" aria-label="Permalink to “Opening: The Story of Independent Developer Xiao Ming”">​</a></h2><p>Xiao Ming is a programmer with three years of experience. One day he suddenly thought: why not make a fitness APP to help users create workout plans and record training data? This idea excited him — he finally found a project he could work on.</p><p>Over the next year, Xiao Ming poured almost all his spare time into it. He built a fully-featured APP — course modules, check-in systems, community features, data analysis — everything it should have. The interface looked pretty good too, at least he thought so.</p><p>On launch day, Xiao Ming was full of anticipation. He spent quite a bit on promotion, and in the first month, 50,000 people downloaded it. Looks like a good start, right?</p><p>But problems soon emerged. After downloading, users would uninstall after one use. The 7-day retention was only 5%. He added some paid features, but almost no users were willing to pay. What frustrated him more was that mature products like Keep, Bohe Health, and FitTime had more complete features and better content — why would users switch to his APP?</p><p>After a year, Xiao Ming lost 200,000 yuan.</p><p>He sat in front of his computer, looking at the dismal data in the backend, with only one question in his mind: My APP is pretty good, why does nobody use it? Even more, why won&#39;t anyone pay for it?</p><p>Xiao Ming&#39;s failure wasn&#39;t because his technology was bad, nor because the product was poorly made. Honestly, his APP had comprehensive features and a nice interface.</p><p><strong>The problem was at the starting point.</strong></p><p>He never asked the most basic question: Do users really need this?</p><p>He saw the fitness APP market was huge, Keep was valued at hundreds of millions, and thought this was a great opportunity. But he didn&#39;t clarify a few things: Why do users need another fitness APP? Compared to Keep, what&#39;s my differentiation? Are users willing to pay for this?</p><p><strong>Wrong direction, the deeper you go, the more wrong you become.</strong> He spent a year making a wrong direction increasingly perfect, only to move further from success.</p><div class="tip custom-block"><p class="custom-block-title">What we&#39;ll do in this chapter</p><p>In this chapter, let&#39;s help Xiao Ming review what happened. Let&#39;s see where his problem really was, and then together find product directions that people are actually willing to pay for.</p><p>We&#39;ll proceed in three steps:</p><p><strong>Act 1: Find Real Needs</strong> — First understand what kind of needs users are willing to pay for</p><p><strong>Act 2: Dig Out Great Ideas</strong> — Learn to mine valuable business opportunities from ordinary ideas</p><p><strong>Act 3: AI Dialogue Refinement</strong> — Use AI to turn ideas into actionable product plans</p></div><hr><h2 id="act-1-finding-real-needs" tabindex="-1">Act 1: Finding Real Needs <a class="header-anchor" href="#act-1-finding-real-needs" aria-label="Permalink to “Act 1: Finding Real Needs”">​</a></h2><p>Xiao Ming was frustrated but didn&#39;t give up. He started reflecting on a question: What kind of needs are users actually willing to pay for?</p><h3 id="xiao-ming-s-confusion-why-won-t-users-pay" tabindex="-1">Xiao Ming&#39;s Confusion: Why Won&#39;t Users Pay? <a class="header-anchor" href="#xiao-ming-s-confusion-why-won-t-users-pay" aria-label="Permalink to “Xiao Ming&#39;s Confusion: Why Won&#39;t Users Pay?”">​</a></h3><p>He went to find a few friends who had used his APP, wanting to hear their honest thoughts.</p><p>Friend A said: &quot;Your APP is pretty good, but I&#39;m already using Keep. Why would I switch?&quot;</p><p>Friend B said: &quot;You want me to record every workout — that&#39;s too much trouble. I&#39;m too lazy to do that.&quot;</p><p>Friend C was more direct: &quot;The free features are enough. Why would I pay?&quot;</p><p>These answers made Xiao Ming suddenly understand where the problem was.</p><p><strong>First problem: Users won&#39;t switch because existing solutions are already good enough.</strong> Mature products like Keep already have comprehensive features, and users have formed habits. The switching cost is high. Why would users switch to your similar product?</p><p><strong>Second problem: Users aren&#39;t willing to change habits.</strong> Recording workouts is too troublesome for users. If a product requires users to change more than 3 habits, it will likely fail.</p><p><strong>Third problem: Too many free alternatives.</strong> Your features are too generic with no unique value. Users can&#39;t find a reason to pay.</p><h3 id="what-is-a-real-need" tabindex="-1">What is a Real Need? <a class="header-anchor" href="#what-is-a-real-need" aria-label="Permalink to “What is a Real Need?”">​</a></h3><p>Xiao Ming started studying successful products that make users willing to pay. He found a common point: these products don&#39;t solve &quot;I think it&#39;s useful&quot; needs, but needs that users are willing to pay for, willing to change behavior for, and willing to endure inconvenience for.</p><p>In other words, <strong>real needs are voted on by users with their feet, not dreamed up by product managers.</strong></p><h3 id="case-studies-products-that-make-users-pay" tabindex="-1">Case Studies: Products That Make Users Pay <a class="header-anchor" href="#case-studies-products-that-make-users-pay" aria-label="Permalink to “Case Studies: Products That Make Users Pay”">​</a></h3><p>Xiao Ming studied several successful cases, trying to understand what pain points they really captured.</p><h4 id="meicai-let-small-restaurant-owners-sleep-better" tabindex="-1">Meicai: Let Small Restaurant Owners Sleep Better <a class="header-anchor" href="#meicai-let-small-restaurant-owners-sleep-better" aria-label="Permalink to “Meicai: Let Small Restaurant Owners Sleep Better”">​</a></h4><p>On the surface, what Meicai does is simple: help restaurants buy vegetables. But if you think carefully, why would restaurant owners use it?</p><p>Because small restaurant owners have to get up at 4 AM every day to go to wholesale markets. It&#39;s exhausting, and they often get cheated. What Meicai does isn&#39;t simple &quot;e-commerce selling vegetables&quot; — it restructured the entire supply chain, letting small restaurant owners sleep better.</p><p>The more painful the pain point, the stronger the willingness to pay. The time and energy saved is more valuable than the money saved on vegetables.</p><h4 id="xiaohongshu-solving-choice-paralysis" tabindex="-1">Xiaohongshu: Solving Choice Paralysis <a class="header-anchor" href="#xiaohongshu-solving-choice-paralysis" aria-label="Permalink to “Xiaohongshu: Solving Choice Paralysis”">​</a></h4><p>On the surface, Xiaohongshu is &quot;sharing overseas shopping experiences.&quot; But why are users willing to spend time reading notes on it?</p><p>Because facing a sea of products, users don&#39;t know what&#39;s worth buying and what isn&#39;t. They need someone they trust to help them filter, save time, and avoid pitfalls.</p><p>What Xiaohongshu really solves are two deep pain points: choice paralysis and lack of trust. Users are willing to pay for &quot;saving time&quot; and &quot;avoiding pitfalls&quot; — that&#39;s why Xiaohongshu succeeded.</p><hr><p>After seeing these cases, Xiao Ming had an important discovery.</p><p>Users never pay for &quot;features&quot; — they pay for &quot;solving fear&quot; and &quot;eliminating anxiety.&quot; Meicai solves small restaurant owners&#39; fear of the hardship of early morning procurement. Xiaohongshu solves users&#39; fear of buying the wrong things.</p><p><strong>Fear drives payment. Anxiety drives action.</strong></p><h3 id="three-layers-of-needs-pain-points-delight-points-itch-points" tabindex="-1">Three Layers of Needs: Pain Points, Delight Points, Itch Points <a class="header-anchor" href="#three-layers-of-needs-pain-points-delight-points-itch-points" aria-label="Permalink to “Three Layers of Needs: Pain Points, Delight Points, Itch Points”">​</a></h3><p>Xiao Ming researched further and found that user needs can be divided into three types:</p><div class="tip custom-block"><p class="custom-block-title">Pain Point — Fear Driven</p><p><strong>Essence:</strong> Problems users are currently experiencing that make them feel pain, anxiety, or inconvenience. Not solving them causes significant discomfort, or even threatens survival or safety.</p><p><strong>Examples:</strong></p><ul><li>Diabetics don&#39;t know how many carbs will spike their blood sugar (Fear: Health threat)</li><li>Small restaurant owners get up at 4 AM to go to wholesale markets (Fear: Survival hardship)</li></ul><p><strong>Key:</strong> Users are willing to pay for this because not solving it is &quot;very painful.&quot;</p></div><div class="tip custom-block"><p class="custom-block-title">Delight Point — Instant Gratification</p><p><strong>Essence:</strong> Users have a need that can be immediately satisfied, producing instant pleasure.</p><p><strong>Examples:</strong></p><ul><li>Food delivery in 30 minutes (Instant satisfaction of hunger)</li><li>One-click generation of beautiful PPT (Time-saving and effort-saving delight)</li></ul><p><strong>Key:</strong> Making users &quot;delighted&quot; is key to retention, but as a standalone payment point it&#39;s weak.</p></div><div class="tip custom-block"><p class="custom-block-title">Itch Point — Virtual Self</p><p><strong>Essence:</strong> Users want to become better, cooler, more refined, but it&#39;s not necessary. Satisfying it makes them happy; not satisfying it is fine too.</p><p><strong>Examples:</strong></p><ul><li>Recording how much water you drink each day (Imagined disciplined life)</li><li>Using AI to add artistic filters to photos (Imagined artistic taste)</li></ul><p><strong>Key:</strong> Users have weak willingness to pay for &quot;itch points&quot; because not solving it doesn&#39;t matter.</p></div><p>What&#39;s the correct priority ranking? A good suggestion is: Pain Points &gt; Delight Points &gt; Itch Points</p><p>Why?</p><ol><li><strong>Pain points are survival needs:</strong> Not solving them means death (or great discomfort). Users have to pay. They&#39;re &quot;painkillers.&quot;</li><li><strong>Delight points are instant rewards:</strong> Make users delighted, and they&#39;ll come. They&#39;re &quot;heroin&quot; (in the positive sense of addictive mechanisms).</li><li><strong>Itch points are desire satisfaction:</strong> Nice to have, easiest to cut. They&#39;re &quot;vitamins&quot; or &quot;luxury goods.&quot;</li></ol><p><strong>Key Insight:</strong> Many product managers make the mistake of marketing itch point products using pain point methods.</p><p>For example: &quot;Recording water intake will make you healthier&quot; — drinking water is indeed healthy, but not recording it won&#39;t make you unhealthy. This is packaging an itch point as a pain point. Users won&#39;t buy it.</p><h3 id="_5-step-method-to-validate-real-needs" tabindex="-1">5-Step Method to Validate Real Needs <a class="header-anchor" href="#_5-step-method-to-validate-real-needs" aria-label="Permalink to “5-Step Method to Validate Real Needs”">​</a></h3><p>Xiao Ming thought: <strong>When I have an idea, how do I quickly judge if it&#39;s worth investing in?</strong></p><p>He learned the 5-step judgment method commonly used by product managers (detailed content in Appendix A):</p><ol><li><p><strong>Step 1: Talk directly with real users to understand their current approach</strong></p><p>Find 10 target users. Ask them: &quot;How do you currently solve this problem?&quot; If users are already using some method, the problem really exists. If users say they don&#39;t need to solve it, it might not be a real need.</p></li><li><p><strong>Step 2: Analyze users&#39; existing alternatives and find your advantages</strong></p><p>Users might currently use other products, Excel, rely on memory, or just endure without solving. You need to figure out the drawbacks of these solutions. Your product needs to be much better than them for users to switch.</p></li><li><p><strong>Step 3: Test if users are willing to pay for your product</strong></p><p>Do pre-sales or collect deposits. Count the percentage of users willing to pay deposits (earning money early indicates correct need):</p><ul><li>Over 10%: Need is real, worth investing</li><li>5% to 10%: Need exists but needs refinement</li><li>Below 5%: Need might not be valid</li></ul></li><li><p><strong>Step 4: Estimate how big this market is and if it can make money</strong></p><p>Calculate three numbers: Total target users × Willingness to pay × Average transaction value. Multiply them to get market size. If the market is too small, it might not be worth doing.</p></li><li><p><strong>Step 5: Think about what moat your product has to prevent copying</strong></p><p>Consider these barriers: Technical difficulty, network effects, brand, cost advantages. These can help you maintain competitiveness long-term.</p></li></ol><p><strong>Act Summary: Xiao Ming&#39;s Takeaways</strong></p><ol><li><p><strong>Standards for Real Needs</strong></p><ul><li>The most important standard is users are willing to pay.</li><li>Users are willing to change behavior for it.</li><li>Without a solution, users would suffer significant loss.</li></ul></li><li><p><strong>Avoid Fake Needs</strong></p><ul><li>Itch points aren&#39;t pain points; they can&#39;t be treated as real needs.</li><li>Markets that are too small can&#39;t support a business model.</li><li>Solutions more complex than the problem will be abandoned by users.</li></ul></li><li><p><strong>Priority Ranking</strong></p><ul><li>The real priority is: Pain Points &gt; Delight Points &gt; Itch Points.</li></ul></li></ol><p><strong>Act Output</strong></p><ul><li>I understand what real needs are.</li><li>I&#39;ve mastered the three-layer classification of needs: pain points, delight points, itch points.</li><li>I&#39;ve learned the 5-step judgment method to validate needs.</li></ul><hr><h2 id="act-2-digging-out-great-ideas" tabindex="-1">Act 2: Digging Out Great Ideas <a class="header-anchor" href="#act-2-digging-out-great-ideas" aria-label="Permalink to “Act 2: Digging Out Great Ideas”">​</a></h2><p>Xiao Ming now knows what real needs are, but he still doesn&#39;t know where to start. He can&#39;t just imagine a need out of thin air, right?</p><p>He decided to start from what he knows best — the people and things around him.</p><h3 id="start-from-yourself-xiao-ming-s-sister" tabindex="-1">Start from Yourself: Xiao Ming&#39;s Sister <a class="header-anchor" href="#start-from-yourself-xiao-ming-s-sister" aria-label="Permalink to “Start from Yourself: Xiao Ming&#39;s Sister”">​</a></h3><p>Xiao Ming thought of his sister. She just had a baby and keeps complaining about having no time to exercise. She can&#39;t lose the belly fat and is very anxious about it.</p><p>One day Xiao Ming asked her: &quot;How are you currently solving the fitness problem?&quot;</p><p>His sister sighed and said: &quot;I follow Keep, but those exercises aren&#39;t suitable for postpartum bodies. After doing them, my lower back hurts even more. Go to a gym? No one to help watch the baby. Hire a personal trainer? One session costs 300-500 yuan, too expensive. Exercise blindly on my own? I&#39;m afraid of getting injured.&quot;</p><p>After hearing this, Xiao Ming felt this might be the real need he was looking for.</p><p>His sister&#39;s troubles are actually quite specific: Fragmented time, needs to care for the baby, no uninterrupted time for exercise; Physical limitations, diastasis recti, pelvic floor muscle laxity, can&#39;t do intense exercise; Psychological anxiety, body shape changed, worried husband will dislike it, socially insecure; Information is too chaotic, too much information online, don&#39;t know what exercises are suitable for postpartum; And loneliness, no one understands their situation, lack of peer support.</p><p>These are all real pain points, not &quot;nice to have&quot; itch points.</p><hr><h3 id="horizontal-segmentation-needs-of-different-user-groups" tabindex="-1">Horizontal Segmentation: Needs of Different User Groups <a class="header-anchor" href="#horizontal-segmentation-needs-of-different-user-groups" aria-label="Permalink to “Horizontal Segmentation: Needs of Different User Groups”">​</a></h3><p>Xiao Ming realized that the &quot;fitness APP&quot; idea was too broad. He wanted to help everyone exercise, but the problem is, everyone&#39;s needs are different.</p><p>He did a horizontal segmentation, dividing &quot;people who want to exercise&quot; into several categories (detailed method in Appendix B):</p><p>Fitness muscle-building crowd needs precise protein intake calculation, manual recording is too troublesome, their willingness to pay is high, pursuing efficiency. Diabetics must strictly control carbs, but it&#39;s hard to estimate when eating out, this is a rigid need, willing to pay, high repurchase rate. Postpartum moms want to recover their figure but don&#39;t have time to calculate, need simple solutions, time-sensitive, need one-stop service. Food delivery crowd eats takeout every day not knowing how many calories consumed, this is a high-frequency scenario, but medium willingness to pay. Graduate exam students need efficient study tools but don&#39;t know what to use, this is a rigid need, but low average transaction value.</p><p>Xiao Ming chose the &quot;postpartum moms&quot; group. Why?</p><p>First, he himself is a user — his sister is a postpartum mom, so he naturally understands this group&#39;s pain points. Second, the pain point is very painful — postpartum recovery anxiety is real, not a &quot;nice to have&quot; itch point. Third, strong willingness to pay — moms are willing to spend money to recover their figure. Fourth, relatively less competition — there&#39;s no product specifically for postpartum moms on the market.</p><div class="tip custom-block"><p class="custom-block-title">Product Manager&#39;s Segmentation Logic</p><p>Why is segmenting user groups so important?</p><p>Because generic tools are hard to win. Big platforms have already occupied the &quot;generic&quot; market, and it&#39;s hard for you to surpass them in features. Specific user groups have more painful needs — postpartum moms&#39; need for exercise is a rigid need, while regular exercisers just think &quot;it would be nice.&quot; Serving a small group well is easier than pleasing everyone to build reputation. Specific user groups&#39; pain points are more concrete, and they&#39;re more willing to pay for solutions.</p></div><hr><h3 id="vertical-deep-dive-complete-user-scenarios" tabindex="-1">Vertical Deep Dive: Complete User Scenarios <a class="header-anchor" href="#vertical-deep-dive-complete-user-scenarios" aria-label="Permalink to “Vertical Deep Dive: Complete User Scenarios”">​</a></h3><p>After finding the user group, Xiao Ming didn&#39;t stop at the single function of &quot;postpartum exercise.&quot; He wanted to understand users&#39; complete scenarios more deeply (detailed method in Appendix C).</p><p>He observed his sister&#39;s day.</p><p>6 AM, the baby just fell asleep, sister has 30 minutes free. She wants to exercise but fears waking the baby, and doesn&#39;t know what movements are safe.</p><p>10 AM, sister is holding the baby to sleep, her lower back is sore. She wants to do some recovery exercises but her hands are occupied.</p><p>3 PM, baby is sleeping, sister wants to exercise. But her body is tired, doesn&#39;t know if she can still do it.</p><p>8 PM, sister finally has time but is very anxious. Looking at herself in the mirror, feeling like life is over, secretly crying while looking at old photos.</p><p>Xiao Ming discovered that his sister&#39;s pain point isn&#39;t &quot;no fitness courses&quot; but &quot;fear and anxiety about postpartum recovery.&quot;</p><hr><div class="info custom-block"><p class="custom-block-title">Product Manager&#39;s Scenario Thinking</p><p>Many people think pain points are just functional requirements, but they&#39;re not. Pain points are emotions in scenarios plus willingness to pay.</p><p>When postpartum moms face their changed bodies in the mirror, the real pain point isn&#39;t &quot;not knowing how to exercise&quot; but fear — worrying about not recovering well, leaving sequelae; Anxiety — looking at themselves in the mirror, feeling like life is over; Helplessness — not knowing where to start, no one to guide; Loneliness — others give birth easily, but I have to recover for so long.</p><p>Good product design solves emotions, not just functions. Behind emotions is the user&#39;s motivation to pay.</p></div><hr><h3 id="value-reconstruction-from-fitness-app-to-postpartum-mom-recovery-assistant" tabindex="-1">Value Reconstruction: From &quot;Fitness APP&quot; to &quot;Postpartum Mom Recovery Assistant&quot; <a class="header-anchor" href="#value-reconstruction-from-fitness-app-to-postpartum-mom-recovery-assistant" aria-label="Permalink to “Value Reconstruction: From &quot;Fitness APP&quot; to &quot;Postpartum Mom Recovery Assistant&quot;”">​</a></h3><p>Based on the above analysis, Xiao Ming redesigned this product.</p><div class="tip custom-block"><p class="custom-block-title">Reconstructed Product Concept: &quot;Postpartum Mom Recovery Assistant&quot;</p><p><strong>Core Positioning:</strong> Not just a fitness tool, but a &quot;personal rehabilitation coach + psychological supporter&quot; for postpartum moms</p><p><strong>Core Features:</strong></p><ol><li><p><strong>Fragmented Training:</strong></p><ul><li>Each session only needs 10-15 minutes</li><li>Can exercise when baby is sleeping</li><li>Provides movements that &quot;can be done while holding the baby&quot;</li></ul></li><li><p><strong>Postpartum-Specific Courses:</strong></p><ul><li>Graded by postpartum stage (0-3 months, 3-6 months, 6+ months)</li><li>Specialized training for diastasis recti, pelvic floor muscle repair</li><li>Every movement has &quot;postpartum precautions&quot; reminders</li></ul></li><li><p><strong>AI Movement Correction:</strong></p><ul><li>Phone camera recognizes movements</li><li>Real-time reminders like &quot;knees too bent,&quot; &quot;back should be straight&quot;</li><li>Avoid injury from incorrect movements</li></ul></li><li><p><strong>Psychological Support Community:</strong></p><ul><li>Private community only for postpartum moms</li><li>Share recovery progress, encourage each other</li><li>Professional psychological counselors on board</li></ul></li><li><p><strong>Personalized Plans:</strong></p><ul><li>Customized based on delivery method (natural/C-section), physical condition</li><li>Considers special needs during breastfeeding</li></ul></li></ol><p><strong>Business Model:</strong></p><ul><li>Basic courses free</li><li>Advanced courses: 99 yuan/month (includes AI movement correction, personalized plans)</li><li>One-on-one coaching: 299 yuan/month (online guidance)</li><li>Community membership: 199 yuan/year (includes psychological support, expert Q&amp;A)</li></ul><p><strong>Competitive Barriers:</strong></p><ul><li>Professionalism: Partnership with postpartum recovery institutions, medical endorsement</li><li>Community stickiness: Postpartum moms&#39; emotional connections are strong</li><li>Data accumulation: More user body data means more precise plans</li></ul><p><strong>Market Size:</strong></p><ul><li>China has about 10 million newborns annually</li><li>Postpartum recovery market is about 50 billion yuan</li><li>Target: Serve 1% of postpartum moms = 100,000 users</li><li>ARPU (Average Revenue Per User): 500 yuan/year</li><li>Potential revenue: 50 million yuan/year</li></ul></div><p>Comparing the original idea with the reconstructed concept:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Original Idea</th><th>Reconstructed</th></tr></thead><tbody><tr><td>Target Users</td><td>All fitness groups (broad)</td><td>Postpartum moms (precise)</td></tr><tr><td>Pain Point Solved</td><td>Recording workouts (itch point)</td><td>Postpartum recovery anxiety (pain point)</td></tr><tr><td>Competitive Barrier</td><td>Technology (easily copied)</td><td>Professionalism + Community + Data</td></tr><tr><td>Willingness to Pay</td><td>Low (many free alternatives)</td><td>High (rigid need + emotional value)</td></tr><tr><td>Expansion Space</td><td>Limited</td><td>Can expand to pregnancy, pre-pregnancy</td></tr></tbody></table><p><strong>This is the evolution from &quot;a feature&quot; to &quot;a product people pay for.&quot;</strong></p><hr><h3 id="more-examples-from-ordinary-ideas-to-great-ideas" tabindex="-1">More Examples: From Ordinary Ideas to Great Ideas <a class="header-anchor" href="#more-examples-from-ordinary-ideas-to-great-ideas" aria-label="Permalink to “More Examples: From Ordinary Ideas to Great Ideas”">​</a></h3><p>Xiao Ming found this method very useful. He used the same method to analyze several other examples, wanting to see if this method is universally applicable (detailed cases in Appendix D).</p><h4 id="example-1-from-calorie-measurement-to-diabetics-eat-with-peace-of-mind" tabindex="-1">Example 1: From &quot;Calorie Measurement&quot; to &quot;Diabetics Eat with Peace of Mind&quot; <a class="header-anchor" href="#example-1-from-calorie-measurement-to-diabetics-eat-with-peace-of-mind" aria-label="Permalink to “Example 1: From &quot;Calorie Measurement&quot; to &quot;Diabetics Eat with Peace of Mind&quot;”">​</a></h4><p>The ordinary idea is photo recognition of food calories, helping people who want to lose weight control their diet. But the problem is there are already mature products like Bohe Health and MyFitnessPal on the market.</p><p>Xiao Ming did a horizontal segmentation and found the diabetic group interesting: They must strictly control carbs, but it&#39;s hard to estimate when eating out. Deep diving into their scenarios: Before meals, don&#39;t know if this dish can be eaten, worried about blood sugar spikes; During meals, need real-time reminders &quot;how many carbs you&#39;ve already had&quot;; After meals, need to record blood sugar changes to see the relationship with diet.</p><p>The reconstructed product is called &quot;Diabetics Eat with Peace of Mind,&quot; positioned as a &quot;dietary safety assistant&quot; for diabetics.</p><hr><h4 id="example-2-from-news-assistant-to-investment-research-intelligence-officer" tabindex="-1">Example 2: From &quot;News Assistant&quot; to &quot;Investment Research Intelligence Officer&quot; <a class="header-anchor" href="#example-2-from-news-assistant-to-investment-research-intelligence-officer" aria-label="Permalink to “Example 2: From &quot;News Assistant&quot; to &quot;Investment Research Intelligence Officer&quot;”">​</a></h4><p>The ordinary idea is aggregating news from various platforms, saving the trouble of opening them one by one. But Toutiao, Tencent News, etc., already do this well.</p><p>Xiao Ming then did horizontal segmentation and found that financial analysts have a special need: they must track dynamics in specific industries, but information is too fragmented. He further deep-dived into their scenarios: in the morning they check overnight U.S. market moves and exchange-rate changes; during the day they track announcements and industry news for portfolio companies; in the afternoon they research potential targets and need large amounts of sector information.</p><p>The reconstructed product is called &quot;Investment Research Intelligence Officer,&quot; positioned as an &quot;information radar and decision assistant&quot; for financial professionals.</p><hr><h4 id="example-3-from-campus-second-hand-platform-to-graduation-clearance-assistant" tabindex="-1">Example 3: From &quot;Campus Second-Hand Platform&quot; to &quot;Graduation Clearance Assistant&quot; <a class="header-anchor" href="#example-3-from-campus-second-hand-platform-to-graduation-clearance-assistant" aria-label="Permalink to “Example 3: From &quot;Campus Second-Hand Platform&quot; to &quot;Graduation Clearance Assistant&quot;”">​</a></h4><p>The ordinary idea is a campus second-hand marketplace. But Xianyu and Zhuanzhuan are already very mature.</p><p>After horizontal segmentation, Xiao Ming found that graduates have a special need: they have too many things, and selling one by one is too troublesome. Deep-diving into their scenarios: they must leave campus within a week before graduation and do not have time to sell slowly; they do not know who needs their items; bargaining, delivery, and payment collection are all too cumbersome.</p><p>The reconstructed product is called &quot;Graduation Clearance Assistant,&quot; positioned as a &quot;move-out asset manager&quot; for graduates.</p><hr><h3 id="act-2-summary-xiao-ming-s-takeaways" tabindex="-1">Act 2 Summary: Xiao Ming&#39;s Takeaways <a class="header-anchor" href="#act-2-summary-xiao-ming-s-takeaways" aria-label="Permalink to “Act 2 Summary: Xiao Ming&#39;s Takeaways”">​</a></h3><p>Through Act 2, Xiao Ming understood:</p><p><strong>1. Start from yourself</strong></p><ul><li>You yourself are a user, so you naturally understand that group&#39;s pain points</li><li>Interest is the best starting point, and passion is the best driving force</li></ul><p><strong>2. Segment users horizontally</strong></p><ul><li>Do not serve &quot;everyone&quot;; find &quot;the segment with the strongest pain&quot;</li><li>The more specific the segment, the more opportunity and stronger willingness to pay</li></ul><p><strong>3. Deep-dive scenarios vertically</strong></p><ul><li>Describe the complete user journey: before use, during use, after use</li><li>Find emotional touchpoints: fear, anxiety, helplessness, loneliness...</li></ul><p><strong>4. Reconstruct value</strong></p><ul><li>Upgrade from a &quot;feature&quot; to a &quot;solution&quot;</li><li>Upgrade from a &quot;tool&quot; to an &quot;assistant/manager/companion&quot;</li></ul><hr><p>📦 <strong>Act Output:</strong></p><ul><li>Found one precise target user group (postpartum moms)</li><li>Understood users&#39; complete scenarios and real emotions</li><li>Reconstructed the product concept with a clear differentiation strategy</li></ul><hr><h2 id="act-3-ai-dialogue-refinement" tabindex="-1">Act 3: AI Dialogue Refinement <a class="header-anchor" href="#act-3-ai-dialogue-refinement" aria-label="Permalink to “Act 3: AI Dialogue Refinement”">​</a></h2><p>Xiao Ming now had a clear product direction: a postpartum mom recovery assistant. But he still did not know exactly how to execute it, where to start, or how difficult the technical implementation would be.</p><p>He decided to use AI to help refine the concept and turn the idea into an actionable plan.</p><h3 id="round-1-present-the-raw-idea" tabindex="-1">Round 1: Present the raw idea <a class="header-anchor" href="#round-1-present-the-raw-idea" aria-label="Permalink to “Round 1: Present the raw idea”">​</a></h3><p>Xiao Ming told AI his idea: &quot;I want to build a postpartum mom recovery assistant app to help postpartum moms recover their figure. But I worry about technical implementation difficulty, especially the AI movement-correction feature. Can one person do this?&quot;</p><hr><h3 id="round-2-ai-helps-plan-the-mvp" tabindex="-1">Round 2: AI helps plan the MVP <a class="header-anchor" href="#round-2-ai-helps-plan-the-mvp" aria-label="Permalink to “Round 2: AI helps plan the MVP”">​</a></h3><p>AI replied: &quot;Great question! Let&#39;s create an MVP (Minimum Viable Product) plan.&quot;</p><p>AI suggested a three-phase plan. Phase 1 is 1-2 months, and the goal is demand validation. Do not build a full app yet; first build a WeChat mini program that only provides postpartum-specific courses (videos) and a check-in community. Use manual guidance for movement feedback: users upload videos and coaches reply. The goal is to validate whether postpartum moms are willing to pay.</p><p>Phase 2 is 3-6 months. If Phase 1 validates successfully, then add core features. Develop AI movement correction, possibly with existing SDKs such as Baidu human-pose recognition. Add personalized plans and optimize community functions.</p><p>Phase 3 is 6-12 months, for scaling. Build an independent app, cooperate with postpartum recovery institutions, and expand to pregnancy and pre-pregnancy scenarios.</p><p>For technical implementation, AI suggested using existing AI capabilities for movement correction, such as Baidu or Tencent APIs, instead of building from scratch, to reduce cost. In the early stage, use a hybrid mode of manual plus AI, then transition gradually.</p><p>For startup cost, mini program development is about 10,000-20,000 RMB if outsourced, or do it yourself with AI IDE. For content creation, cooperate with postpartum recovery coaches. For promotion, start from mom groups and Xiaohongshu.</p><p>Validation KPI: 100 users in the first month and a 10% paid conversion rate. If reached, demand is real and you continue investing; if not, adjust direction in time.</p><hr><h3 id="round-3-xiao-ming-raises-concerns" tabindex="-1">Round 3: Xiao Ming raises concerns <a class="header-anchor" href="#round-3-xiao-ming-raises-concerns" aria-label="Permalink to “Round 3: Xiao Ming raises concerns”">​</a></h3><p>After thinking, Xiao Ming asked again: &quot;I am worried about content production. Postpartum recovery courses require professional guidance, and I do not have a medical background. How can I ensure course quality?&quot;</p><hr><h3 id="round-4-ai-provides-solutions" tabindex="-1">Round 4: AI provides solutions <a class="header-anchor" href="#round-4-ai-provides-solutions" aria-label="Permalink to “Round 4: AI provides solutions”">​</a></h3><p>AI replied: &quot;This is a common concern for technical founders, but there are solutions.&quot;</p><p>Solution 1 is to collaborate with professionals. Work with postpartum recovery coaches or hospital nutrition doctors. You provide the technology and product; they provide professional content. Use a revenue-sharing model.</p><p>Solution 2 is to integrate high-quality existing content. In the early stage, use public postpartum recovery videos, such as from YouTube or Bilibili. Do content review and curation first, then produce original content later.</p><p>Solution 3 is user-generated content. Encourage experienced moms to share their recovery methods, and use community voting to filter quality content, gradually building a content ecosystem.</p><p>AI recommended starting with Solution 1. Specific operation: find 2-3 postpartum recovery coaches and discuss cooperation; you build the product, they provide courses. Revenue split: you take 70%, they take 30%. This ensures quality while reducing cost. Early-stage course production cost can be zero with revenue sharing; you only invest development time and promotion cost.</p><p><strong>My suggestion: start with Solution 1</strong></p><p>Specific actions:</p><ol><li>Find 2-3 postpartum recovery coaches</li><li>Propose cooperation: you build the product, they provide courses</li><li>Revenue split: you take 70%, they take 30%</li><li>This ensures content quality and lowers cost</li></ol><p><strong>Early-stage cost:</strong></p><ul><li>Course production: 0 RMB (revenue-share model)</li><li>You only need to invest development time and promotion cost</li></ul><p>:::</p><hr><h3 id="round-5-xiao-ming-asks-about-promotion" tabindex="-1">Round 5: Xiao Ming asks about promotion <a class="header-anchor" href="#round-5-xiao-ming-asks-about-promotion" aria-label="Permalink to “Round 5: Xiao Ming asks about promotion”">​</a></h3><p>Xiao Ming had one final concern: &quot;Will promotion cost be high? How do I find postpartum moms?&quot;</p><hr><h3 id="round-6-ai-provides-promotion-strategy" tabindex="-1">Round 6: AI provides promotion strategy <a class="header-anchor" href="#round-6-ai-provides-promotion-strategy" aria-label="Permalink to “Round 6: AI provides promotion strategy”">​</a></h3><p>AI replied: &quot;This group is actually easy to find, and promotion cost can be very low.&quot;</p><p>The most recommended channel is Xiaohongshu. Search keywords like &quot;postpartum recovery&quot; and &quot;diastasis recti,&quot; find related creators, and DM for collaboration. Offer &quot;1 month free trial&quot; in exchange for promotion, with near-zero cost.</p><p>Second is mom groups. Search WeChat groups and QQ groups. Join under the name of &quot;postpartum recovery experience sharing,&quot; share useful content, do not post direct ads, and gradually build trust.</p><p>You can also cooperate with hospital obstetrics departments by providing free postpartum recovery guidance and distributing flyers in hospitals, with only a few hundred RMB printing cost. Or cooperate with maternal-and-infant stores, place promotional materials, and provide trial cards with purchases, with only trial-card production cost.</p><p>Validation metrics: in the first month, 100 users and 10 paid users (10% conversion rate), total promotion cost under 1000 RMB, and customer acquisition cost under 10 RMB per user. If these metrics are met, demand is real and you can continue investing.</p><hr><h3 id="final-xiao-ming-now-has-a-clear-plan" tabindex="-1">Final: Xiao Ming now has a clear plan <a class="header-anchor" href="#final-xiao-ming-now-has-a-clear-plan" aria-label="Permalink to “Final: Xiao Ming now has a clear plan”">​</a></h3><p>After 6 rounds of dialogue, Xiao Ming finally had a clear plan.</p><p>Phase 1 (1-2 months): build a WeChat mini program, cooperate with 2-3 postpartum recovery coaches (revenue share), provide only postpartum-specific courses (videos) and a check-in community, and use manual movement guidance. Target: 100 users and 10% paid conversion.</p><p>Phase 2 (3-6 months): if Phase 1 validates successfully, continue investing. Add AI movement correction, personalized plans, and optimize community features.</p><p>Phase 3 (6-12 months): develop an independent app, cooperate with postpartum recovery institutions, and expand to pregnancy and pre-pregnancy phases.</p><p>Startup cost is very low: development done by yourself using AI IDE (0 RMB), content with coach revenue sharing (0 RMB in early stage), and promotion via Xiaohongshu plus mom groups (under 1000 RMB). Total cost under 1000 RMB.</p><hr><h3 id="the-5-step-method-for-ai-dialogue-refinement" tabindex="-1">The 5-step method for AI dialogue refinement <a class="header-anchor" href="#the-5-step-method-for-ai-dialogue-refinement" aria-label="Permalink to “The 5-step method for AI dialogue refinement”">​</a></h3><p>From this case, Xiao Ming summarized a standard AI dialogue workflow (see Appendix E for details).</p><p><strong>Step 1: Present the raw idea.</strong> Describe your initial idea, even if rough. Tell AI your concerns, such as heavy competition or unclear differentiation.</p><p><strong>Step 2: Ask AI to plan the MVP.</strong> What should the minimum viable product include? How many phases? What are the goals in each phase? How difficult is implementation?</p><p><strong>Step 3: Raise your concerns.</strong> Technical difficulty? Content production cost? Promotion cost? User acquisition difficulty? Tell AI all your concerns.</p><p><strong>Step 4: Ask AI for concrete solutions.</strong> AI will provide specific suggestions for your concerns. Compare options and choose the best one. Estimate costs.</p><p><strong>Step 5: Finalize the plan.</strong> Organize a clear action plan and set validation metrics. If targets are not met, adjust in time.</p><p><strong>Prompt template:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to build a [product concept],</span></span>
<span class="line"><span>but I am worried about [your concern].</span></span>
<span class="line"><span>Please help me:</span></span>
<span class="line"><span>1. Plan an MVP</span></span>
<span class="line"><span>2. Give concrete technical implementation suggestions</span></span>
<span class="line"><span>3. Estimate cost</span></span>
<span class="line"><span>4. Set validation metrics</span></span></code></pre></div><hr><h3 id="act-3-summary-xiao-ming-s-takeaways" tabindex="-1">Act 3 Summary: Xiao Ming&#39;s Takeaways <a class="header-anchor" href="#act-3-summary-xiao-ming-s-takeaways" aria-label="Permalink to “Act 3 Summary: Xiao Ming&#39;s Takeaways”">​</a></h3><p>Through Act 3, Xiao Ming understood three things.</p><p><strong>First, use AI dialogue to refine product concepts.</strong> Do not expect one conversation to produce a perfect answer; iterate through multiple rounds. Tell AI your observations, experiences, and feedback from people around you. If AI suggestions are unreasonable, point it out in time. Always end with a concrete action plan.</p><p><strong>Second, MVP core principles.</strong> Keep it minimal, and only build the core function. Make it verifiable, so you can quickly validate whether demand is real. Keep it low cost, and validate with the smallest possible investment.</p><p><strong>Third, validation metrics.</strong> Paid conversion &gt; 10% means demand is real and worth investment. Paid conversion 5-10% means demand exists but needs refinement. Paid conversion &lt; 5% means demand does not hold and direction should be adjusted.</p><hr><p>📦 <strong>Chapter Output:</strong></p><ul><li>A clear MVP plan</li><li>A known technical implementation path</li><li>Defined validation metrics</li></ul><hr><h2 id="final-act-your-action" tabindex="-1">Final Act: Your Action <a class="header-anchor" href="#final-act-your-action" aria-label="Permalink to “Final Act: Your Action”">​</a></h2><h3 id="memory-mantra" tabindex="-1">Memory mantra <a class="header-anchor" href="#memory-mantra" aria-label="Permalink to “Memory mantra”">​</a></h3><p><strong>Start from one person, one thing, one entry point. Segment horizontally, dig vertically, refine through AI dialogue, and only build after five-step validation.</strong></p><p><strong>Explanation:</strong></p><ul><li><strong>One person:</strong> Start from yourself because you naturally understand this group</li><li><strong>One thing:</strong> Focus on one concrete thing and do not be greedy</li><li><strong>One entry point:</strong> Find a sharp entry point, and the more segmented, the better</li><li><strong>Horizontal segmentation:</strong> Find users with strongest willingness to pay</li><li><strong>Vertical deep dive:</strong> Understand users&#39; complete journey</li><li><strong>AI dialogue:</strong> Refine product concepts with AI dialogue</li><li><strong>Five-step validation:</strong> Use the five-step method to validate demand authenticity</li></ul><hr><h3 id="post-class-exercise" tabindex="-1">Post-class exercise <a class="header-anchor" href="#post-class-exercise" aria-label="Permalink to “Post-class exercise”">​</a></h3><p>Choose one small annoyance from your daily life and expand it using this chapter&#39;s method:</p><div class="tip custom-block"><p class="custom-block-title">Exercise Task</p><p><strong>1. Describe this annoyance</strong> (in one sentence)</p><ul><li>Example: &quot;I want to build a bookkeeping app to help users record spending.&quot;</li></ul><p><strong>2. Horizontal segmentation: find 3 user groups that may have different needs</strong></p><ul><li>Example: small business owners, parents of overseas students, freelancers</li></ul><p><strong>3. Select one group, then deep-dive vertically: describe their complete scenario and real emotions</strong></p><ul><li>Example: scenario of overseas-student parents - they want to know how much their child spends abroad, but the child does not tell them</li></ul><p><strong>4. Reconstruct product concept: evolve from &quot;one feature&quot; into &quot;one solution&quot;</strong></p><ul><li>Example: &quot;Overseas Spending Steward&quot; - not just bookkeeping, but giving parents confidence and visibility into overseas spending</li></ul><p><strong>5. Evaluate your idea with the validation checklist</strong> (see Appendix F)</p><p><strong>Share your analysis in the community and discuss with other learners!</strong></p></div><hr><h2 id="appendix-sop-methodology" tabindex="-1">Appendix: SOP Methodology <a class="header-anchor" href="#appendix-sop-methodology" aria-label="Permalink to “Appendix: SOP Methodology”">​</a></h2><h3 id="appendix-a-5-step-judgment-method-for-need-analysis" tabindex="-1">Appendix A: 5-Step judgment method for need analysis <a class="header-anchor" href="#appendix-a-5-step-judgment-method-for-need-analysis" aria-label="Permalink to “Appendix A: 5-Step judgment method for need analysis”">​</a></h3><p>When you have an idea, how can you quickly judge whether it is worth investing in?</p><p><strong>Step 1: User validation - find 10 target users</strong></p><p><strong>Do not ask:</strong> &quot;Will you use my product?&quot; (false-positive rate is around 90%)</p><p><strong>Ask instead:</strong></p><ol><li>&quot;How do you currently solve this problem?&quot; (understand real behavior)</li><li>&quot;How many times did this problem bother you in the last week?&quot; (understand frequency)</li><li>&quot;How much money/time did you spend to solve it?&quot; (understand willingness to pay)</li><li>&quot;If there is a solution but it requires changing habits, are you willing?&quot; (understand change cost)</li></ol><p><strong>Decision criteria:</strong></p><ul><li>If more than 3 users say &quot;this gives me headache every day&quot; - it may be a pain point</li><li>If users say &quot;interesting, but not urgent&quot; - most likely an itch point</li><li>If users say &quot;I currently use XX, but not satisfied&quot; - there is opportunity</li></ul><p><strong>Key question:</strong> what method do users currently use to solve this problem?</p><table tabindex="0"><thead><tr><th>Alternative Type</th><th>Description</th><th>Opportunity Assessment</th></tr></thead><tbody><tr><td><strong>No alternative</strong></td><td>Users silently endure</td><td>Big opportunity, but market education is required</td></tr><tr><td><strong>Using clumsy methods</strong></td><td>Excel, manual work, multi-person collaboration</td><td>Good opportunity, users want better solutions</td></tr><tr><td><strong>Combining multiple tools</strong></td><td>Tool A + Tool B + Tool C</td><td>Good opportunity, integration has value</td></tr><tr><td><strong>Using mature products</strong></td><td>But users are unsatisfied</td><td>Opportunity exists, but differentiation is needed</td></tr><tr><td><strong>Using mature products</strong></td><td>Users are satisfied</td><td>Very small opportunity unless there is disruptive innovation</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">What is &quot;disruptive innovation&quot;?</p><p><strong>Simple definition:</strong> not making products incrementally better, but serving previously overlooked user groups with a simpler/cheaper approach.</p><p><strong>Examples:</strong></p><ul><li>Traditional phones -&gt; smartphones (not just more functions, but a completely different interaction model)</li><li>Traditional taxis -&gt; Didi/Uber (not better cars, but on-demand ride calling anywhere)</li><li>Traditional bookstores -&gt; e-books (not more books, but easier carrying and purchasing)</li></ul><p><strong>Key point:</strong> disruptive innovation often starts from low-end markets or new user groups, and then gradually moves upward.</p></div><p><strong>Cases:</strong></p><ul><li>Diabetics currently control diet by &quot;experience + guessing&quot; (very clumsy method) -&gt; big opportunity</li><li>Ordinary dieters use Bohe Health (mature product, medium satisfaction) -&gt; opportunity for vertical segmentation</li><li>Students use WeChat groups for second-hand trading (multiple tools stitched together) -&gt; opportunity for integration</li></ul><p><strong>Most effective method: presale or deposit</strong></p><p><strong>Steps:</strong></p><ol><li>Create a simple landing page and describe your product concept</li><li>Put a &quot;presale&quot; or &quot;reservation&quot; button</li><li>See how many people are willing to pay (even 1 RMB counts)</li></ol><p><strong>Decision criteria:</strong></p><ul><li>Users willing to pay deposit &gt; 10%: demand is real and worth doing</li><li>5%-10%: demand exists but needs refinement</li><li>&lt; 5%: demand may not be valid, or product concept has issues</li></ul><p><strong>Note:</strong> many people say &quot;I will buy.&quot; The people who actually pay are your real target users.</p><p><strong>Simple formula:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Potential market size = target user count × willingness to pay × average order value</span></span></code></pre></div><p><strong>Case: campus second-hand trading platform</strong></p><ul><li>Target users: 40 million college students in China</li><li>With second-hand trading demand: 50% = 20 million</li><li>Willing to use platform: 10% = 2 million</li><li>Annual transaction frequency: 2 times</li><li>Platform commission: 5%</li><li>Average order value: 100 RMB</li><li>Potential market size = 2,000,000 × 2 × 100 × 5% = 20 million RMB/year</li></ul><p><strong>Decision criteria:</strong></p><ul><li>Market size &gt; 1 billion RMB: large track, worth pursuing</li><li>100 million-1 billion RMB: medium/small track, possible but ceiling is visible</li><li>&lt; 100 million RMB: niche market, suitable for side business or a small-and-beautiful business</li></ul><p><strong>Key question:</strong> if the product succeeds, what if others copy it?</p><p><strong>Common moat types:</strong></p><table tabindex="0"><thead><tr><th>Moat Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Network effects</strong></td><td>More users -&gt; more product value</td><td>WeChat, Didi</td></tr><tr><td><strong>Data accumulation</strong></td><td>More data -&gt; better algorithm</td><td>Toutiao, Douyin</td></tr><tr><td><strong>Brand cognition</strong></td><td>Occupying user mindshare</td><td>Coca-Cola, Nike</td></tr><tr><td><strong>Scale effects</strong></td><td>Larger scale -&gt; lower costs</td><td>JD logistics, Amazon</td></tr><tr><td><strong>Technical patents</strong></td><td>Core technology barriers</td><td>Huawei, DJI</td></tr><tr><td><strong>Switching costs</strong></td><td>High migration cost for users</td><td>Enterprise software, operating systems</td></tr></tbody></table><p><strong>Early-stage reality:</strong></p><ul><li>Most early projects do not have clear moats</li><li>But that is fine; the key is to <strong>move fast</strong></li><li>Occupy market first, then build barriers</li></ul><hr><h3 id="appendix-b-horizontal-user-segmentation-method" tabindex="-1">Appendix B: Horizontal user-segmentation method <a class="header-anchor" href="#appendix-b-horizontal-user-segmentation-method" aria-label="Permalink to “Appendix B: Horizontal user-segmentation method”">​</a></h3><p>Do not try to serve &quot;all XX users.&quot; Instead, find <strong>one specific group</strong> with sharper and more concrete needs.</p><p><strong>Step 1: List all possible segmented user groups</strong></p><p>For your product concept, list all possible user groups.</p><p><strong>Step 2: Evaluate the business value of each group</strong></p><table tabindex="0"><thead><tr><th>Evaluation Dimension</th><th>Description</th></tr></thead><tbody><tr><td>Pain intensity</td><td>Is this group&#39;s need a pain point or itch point?</td></tr><tr><td>Willingness to pay</td><td>How much are they willing to pay for a solution?</td></tr><tr><td>Market size</td><td>How many people are in this group?</td></tr><tr><td>Competition level</td><td>Are current solutions satisfactory?</td></tr><tr><td>Your understanding of this group</td><td>Do you understand this group? Do you have access channels?</td></tr></tbody></table><p><strong>Step 3: Choose one group for deep analysis</strong></p><p>Choose the one that is:</p><ul><li>most painful</li><li>highest willingness to pay</li><li>best understood by you</li><li>relatively less competitive</li></ul><div class="tip custom-block"><p class="custom-block-title">Segmentation Example</p><p><strong>Product concept:</strong> bookkeeping app</p><table tabindex="0"><thead><tr><th>Segmented Group</th><th>Pain Point</th><th>Willingness to Pay</th><th>Market Size</th><th>Competition</th></tr></thead><tbody><tr><td>Ordinary office workers</td><td>Recording is troublesome</td><td>Low</td><td>Large</td><td>High</td></tr><tr><td>Small business owners</td><td>Personal/company spending is mixed up</td><td>High</td><td>Medium</td><td>Medium</td></tr><tr><td>Freelancers</td><td>Unstable income, need cash-flow forecast</td><td>High</td><td>Medium</td><td>Medium</td></tr><tr><td>Parents of overseas students</td><td>Want to know child&#39;s spending but child does not say</td><td>High</td><td>Small</td><td>Low</td></tr></tbody></table><p><strong>Chosen segment:</strong> parents of overseas students (strongest pain point, high willingness to pay, relatively low competition)</p></div><hr><h3 id="appendix-c-vertical-scenario-deep-dive-method" tabindex="-1">Appendix C: Vertical scenario deep-dive method <a class="header-anchor" href="#appendix-c-vertical-scenario-deep-dive-method" aria-label="Permalink to “Appendix C: Vertical scenario deep-dive method”">​</a></h3><p>After finding the user group, do not stop at a single feature. You need to understand the user&#39;s <strong>complete scenario</strong>.</p><p><strong>Step 1: Describe one full day of the user</strong></p><p>From morning to night, describe the complete scenario in which the user interacts with your product.</p><p><strong>Step 2: Analyze pain points in each scenario</strong></p><p>In each scenario, what problems does the user encounter? What emotions appear?</p><p><strong>Step 3: Find emotional touchpoints</strong></p><p>Fear, anxiety, helplessness, loneliness, anger, regret...</p><p><strong>Step 4: Reconstruct value</strong></p><p>Based on scenarios and emotions, reconstruct product value.</p><div class="tip custom-block"><p class="custom-block-title">Deep-Dive Example</p><p><strong>User group:</strong> postpartum moms</p><table tabindex="0"><thead><tr><th>Time</th><th>Scenario</th><th>Pain Point</th><th>Emotion</th></tr></thead><tbody><tr><td>6 AM</td><td>Baby just fell asleep, 30 minutes free</td><td>Do not know what movement is safe</td><td>Fear</td></tr><tr><td>10 AM</td><td>Holding baby to help sleep, lower back soreness</td><td>Hands occupied, wants recovery exercise</td><td>Anxiety</td></tr><tr><td>3 PM</td><td>Baby sleeping, wants to exercise</td><td>Body is tired, unsure if can continue</td><td>Helplessness</td></tr><tr><td>8 PM</td><td>Finally has time</td><td>Sees body in mirror and feels life is over</td><td>Depression</td></tr><tr><td>Long term</td><td>No one understands</td><td>Feels like only self suffers this much</td><td>Loneliness</td></tr></tbody></table><p><strong>Reconstructed value:</strong> upgrade from &quot;fitness tool&quot; to &quot;rehab coach + psychological supporter&quot;</p></div><hr><h3 id="appendix-d-more-examples-from-ordinary-ideas-to-great-ideas" tabindex="-1">Appendix D: More examples from ordinary ideas to great ideas <a class="header-anchor" href="#appendix-d-more-examples-from-ordinary-ideas-to-great-ideas" aria-label="Permalink to “Appendix D: More examples from ordinary ideas to great ideas”">​</a></h3><h4 id="example-1-from-bookkeeping-app-to-overseas-spending-steward" tabindex="-1">Example 1: From &quot;bookkeeping app&quot; to &quot;Overseas Spending Steward&quot; <a class="header-anchor" href="#example-1-from-bookkeeping-app-to-overseas-spending-steward" aria-label="Permalink to “Example 1: From &quot;bookkeeping app&quot; to &quot;Overseas Spending Steward&quot;”">​</a></h4><p><strong>Ordinary idea:</strong> automatic bookkeeping app, connecting bank cards to auto-categorize spending</p><p><strong>Problem:</strong> there are already SuiShouJi, WaCai, Alipay bills...</p><p><strong>Horizontal segmentation:</strong></p><ul><li>Parents of overseas students: want to know how much their child spends abroad and whether they overspend</li></ul><p><strong>Vertical deep dive:</strong></p><ul><li>Pain point is not bookkeeping but <strong>&quot;loss of control&quot;</strong> - do not know how much the child spends or where money goes</li><li>Scenario: every month parents see credit-card bills, but the child never proactively explains spending</li></ul><p><strong>Reconstructed concept:</strong> &quot;Overseas Spending Steward&quot; - not only bookkeeping, but letting parents &quot;have clear visibility&quot; on overseas spending</p><p><strong>Core features:</strong></p><ul><li>Real-time child spending sync</li><li>Overspending alerts</li><li>Monthly spending analysis reports</li><li>Peer comparison among similar students (&quot;your child spends 20% above average&quot;)</li></ul><hr><h4 id="example-2-from-pomodoro-tool-to-remote-work-proof" tabindex="-1">Example 2: From &quot;Pomodoro tool&quot; to &quot;Remote Work Proof&quot; <a class="header-anchor" href="#example-2-from-pomodoro-tool-to-remote-work-proof" aria-label="Permalink to “Example 2: From &quot;Pomodoro tool&quot; to &quot;Remote Work Proof&quot;”">​</a></h4><p><strong>Ordinary idea:</strong> Pomodoro app to help users focus</p><p><strong>Problem:</strong> phones already have screen-time stats, plus Forest and Pomodoro Todo...</p><p><strong>Horizontal segmentation:</strong></p><ul><li>Remote workers: need to prove to managers that they are truly working</li></ul><p><strong>Vertical deep dive:</strong></p><ul><li>Pain point is not &quot;cannot focus,&quot; but <strong>&quot;trust crisis&quot;</strong> - if manager cannot see me, how do I prove I am working?</li><li>Scenario: every day after work, manager asks &quot;how was your progress today?&quot; and there is no proof</li></ul><p><strong>Reconstructed concept:</strong> &quot;Remote Work Proof&quot; - helping remote workers build trust with employers</p><p><strong>Core features:</strong></p><ul><li>Automatic work-time tracking</li><li>Productivity reports</li><li>Screen activity summaries (privacy-protected)</li><li>Auto-generated daily work report sent to supervisor</li></ul><hr><h4 id="example-3-from-second-hand-book-trading-to-picture-book-library" tabindex="-1">Example 3: From &quot;second-hand book trading&quot; to &quot;Picture Book Library&quot; <a class="header-anchor" href="#example-3-from-second-hand-book-trading-to-picture-book-library" aria-label="Permalink to “Example 3: From &quot;second-hand book trading&quot; to &quot;Picture Book Library&quot;”">​</a></h4><p><strong>Ordinary idea:</strong> second-hand book trading platform</p><p><strong>Problem:</strong> there are already Duozhuayu, Xianshu, and Kongfuzi used-book marketplaces...</p><p><strong>Horizontal segmentation:</strong></p><ul><li>Mom users: children&#39;s picture books become idle after reading, but buying new books is expensive</li></ul><p><strong>Vertical deep dive:</strong></p><ul><li>Pain point is not &quot;books are expensive,&quot; but <strong>&quot;short lifecycle of picture books&quot;</strong> - books for age 3 are not read at age 4</li><li>Scenario: home is full of picture books that children no longer read, but throwing them away feels wasteful</li></ul><p><strong>Reconstructed concept:</strong> &quot;Picture Book Library delivered to your home&quot; - not selling used books, but providing &quot;rental of usage rights&quot;</p><p><strong>Core features:</strong></p><ul><li>Picture book subscription (mail 5 age-appropriate books each month, return after reading, then rotate new ones)</li><li>Reading progress tracking</li><li>Age-appropriate recommendations</li><li>Sterilization guarantee</li></ul><hr><h3 id="appendix-e-5-step-method-to-refine-product-concepts-via-ai-dialogue" tabindex="-1">Appendix E: 5-step method to refine product concepts via AI dialogue <a class="header-anchor" href="#appendix-e-5-step-method-to-refine-product-concepts-via-ai-dialogue" aria-label="Permalink to “Appendix E: 5-step method to refine product concepts via AI dialogue”">​</a></h3><p>Use multi-round AI dialogue to gradually refine ordinary ideas into precise, executable product concepts.</p><p><strong>Operation:</strong></p><ul><li>Describe your initial idea (even if rough)</li><li>Tell AI your concerns (heavy competition, unclear differentiation, etc.)</li></ul><p><strong>Prompt:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to build [product concept],</span></span>
<span class="line"><span>but I found [problem/concern].</span></span></code></pre></div><p><strong>Operation:</strong></p><ul><li>Ask AI to create a minimum viable product plan</li><li>Discuss implementation difficulty and costs</li><li>Define validation metrics</li></ul><p><strong>Prompt:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please help me:</span></span>
<span class="line"><span>1. Plan an MVP</span></span>
<span class="line"><span>2. Provide concrete technical implementation advice</span></span>
<span class="line"><span>3. Estimate cost</span></span>
<span class="line"><span>4. Define validation metrics</span></span></code></pre></div><p><strong>Operation:</strong></p><ul><li>Technical difficulty?</li><li>Content production cost?</li><li>Promotion cost?</li><li>User acquisition difficulty?</li></ul><p><strong>Prompt:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I am worried about:</span></span>
<span class="line"><span>1. [Concern 1]</span></span>
<span class="line"><span>2. [Concern 2]</span></span>
<span class="line"><span>3. [Concern 3]</span></span></code></pre></div><p><strong>Operation:</strong></p><ul><li>Provide concrete solutions for your concerns</li><li>Compare multiple options and choose the best</li><li>Estimate costs</li></ul><p><strong>Prompt:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please provide concrete solutions for my concerns.</span></span></code></pre></div><p><strong>Operation:</strong></p><ul><li>Organize a clear action plan</li><li>Set validation metrics</li><li>If metrics are not met, adjust direction quickly</li></ul><p><strong>Prompt:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please help me organize a clear action plan.</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Key techniques</p><ul><li><strong>Multi-round dialogue:</strong> do not expect a perfect answer in one round; iterate</li><li><strong>Provide information:</strong> tell AI your observations, experiences, and people-around-you feedback</li><li><strong>Challenge AI:</strong> if AI suggestions are unreasonable, call that out in time</li><li><strong>Focus on execution:</strong> always end with a concrete action plan</li></ul></div><hr><h3 id="appendix-f-need-validation-checklist" tabindex="-1">Appendix F: Need validation checklist <a class="header-anchor" href="#appendix-f-need-validation-checklist" aria-label="Permalink to “Appendix F: Need validation checklist”">​</a></h3><p>Before deciding to invest development time, validate your idea with the checklist below - <strong>the core question is always: will users pay for this?</strong></p><div class="tip custom-block"><p class="custom-block-title">Need Validation Checklist</p><p><strong>1. User profile clarity</strong></p><ul><li>☐ Can you describe your target user in one sentence?</li><li>☐ Can you state what alternative they currently use?</li><li>☐ Can you describe specific details of their usage scenario?</li><li>☐ Does this user group have payment capability?</li></ul><p><strong>2. Pain intensity evaluation</strong></p><ul><li>☐ What cost do users pay now to solve this problem? (time/money/effort)</li><li>☐ If they do not solve it, what consequence follows?</li><li>☐ Are users actively seeking solutions?</li><li>☐ How much are users willing to pay for this?</li></ul><p><strong>3. Solution differentiation</strong></p><ul><li>☐ Compared with existing solutions, what is your advantage?</li><li>☐ Is that advantage strong enough to make users switch?</li><li>☐ How hard is it for big platforms to copy your feature?</li><li>☐ Is your differentiation enough to support paid conversion?</li></ul><p><strong>4. Business model feasibility</strong></p><ul><li>☐ Are users willing to pay? How much? (must be tested in reality)</li><li>☐ What is rough customer acquisition cost?</li><li>☐ Can user lifetime value (LTV) cover customer acquisition cost (CAC)?</li><li>☐ Are there additional monetization paths? (ads, value-added services, B2B, etc.)</li></ul><p><strong>5. Rapid validation plan</strong></p><ul><li>☐ Can you build a testable prototype with minimum cost in 1-2 weeks?</li><li>☐ Can you find 10 target users for interviews?</li><li>☐ Can you design an experiment to validate the core hypothesis?</li><li>☐ Can you ask users to prepay deposits to validate willingness to pay?</li></ul></div><p><strong>Do not ask &quot;Will you use this product?&quot;</strong><br> This question mostly gives false positives.</p><p><strong>Ask instead:</strong></p><ul><li>&quot;How do you currently solve this problem?&quot; (understand real behavior)</li><li>&quot;How many times did this problem bother you in the last week?&quot; (understand frequency)</li><li>&quot;If there is a solution, but it requires changing your current habit, are you willing?&quot; (understand change cost)</li><li>&quot;If it costs XX RMB, will you buy?&quot; (understand willingness to pay)</li></ul><p><strong>Best validation:</strong> ask users to prepay deposits. Many people say they are willing to pay, but those who actually pay are your real target users.</p><p><strong>Key metrics:</strong></p><ul><li>Deposit-paying user ratio &gt; 10%: demand is real and worth investment</li><li>Deposit-paying ratio 5%-10%: demand exists but needs refinement</li><li>Deposit-paying ratio &lt; 5%: demand is invalid, or product concept has issues</li></ul><hr><h2 id="chapter-summary" tabindex="-1">Chapter Summary <a class="header-anchor" href="#chapter-summary" aria-label="Permalink to “Chapter Summary”">​</a></h2><p>In this chapter, through Xiao Ming&#39;s story, we learned how to evaluate product ideas from a product-manager perspective - <strong>the core is always: will users pay for this?</strong></p><div class="info custom-block"><p class="custom-block-title">Core points</p><p><strong>1. Three standards of real demand:</strong></p><ul><li>Users are willing to pay for it (the most important standard)</li><li>Users are willing to change behavior for it</li><li>If no solution exists, users suffer clear loss</li></ul><p><strong>2. Path from ordinary idea to product people will pay for:</strong></p><ul><li><strong>Horizontal segmentation:</strong> find a specific user group, and the more segmented, the stronger willingness to pay</li><li><strong>Vertical deep dive:</strong> understand complete scenarios, solving emotions rather than only functions</li><li><strong>Value reconstruction:</strong> evolve from tools into solutions and build reasons to pay</li></ul><p><strong>3. Avoid fake-demand traps:</strong></p><ul><li>Solving pseudo pain points (itch points instead of pain points)</li><li>Market size is too small to support a business model</li><li>Solution is more complex than the problem itself</li></ul><p><strong>4. How to validate willingness to pay:</strong></p><ul><li>Interview 10 target users in depth</li><li>Ask users to prepay deposits to verify true willingness</li><li>Only when deposit-paying ratio &gt; 10% is it worth investing</li></ul><p><strong>5. Refine product concepts with AI dialogue:</strong></p><ul><li>Iterate through multiple rounds</li><li>Focus on execution and action plans</li><li>Set validation metrics and adjust direction promptly</li></ul></div><p><strong>Remember:</strong> good product managers do not create demand from thin air. They discover real needs that are <strong>ignored, underestimated, or poorly satisfied</strong>, then find ways to make users willing to pay.</p><p>In the next chapter, we will bring validated ideas and start learning how to use AI IDE to turn them into interactive product prototypes.</p>`,337))])}}});export{b as __pageData,v as default};
